78	/// Declares the crawl, with no connection and no I/O. Each handler owns a clone of the handles it
79	/// uses, so the declaration outlives this function.
80	pub fn books_crawl() -> Result<BooksCrawl, Error> {
81	    let mut crawl = Crawl::new();
82	    let books = crawl.dataset(DatasetDeclaration::<Book>::new("books").key(&["url"]))?;
83	    let home = crawl.label::<()>("home")?;
84	    let category = crawl.label::<CategoryPayload>("category")?;
85	    let book = crawl.label::<BookPayload>("book")?;
86	
87	    let to_category = category.clone();
88	    crawl.handle(&home, async move |ctx: CrawlContext<()>| {
89	        // The nested list leaves out the top-level "Books"; each link's own text is its Payload.
90	        let links = ctx.page().locator(".side_categories ul ul a");
91	        let payload = |link: &LinkInfo| {
92	            Some(CategoryPayload {
93	                name: link.text.trim().to_owned(),
94	            })
95	        };
96	        ctx.enqueue_links_with(&links, &to_category, payload)
97	            .await?;
98	        Ok(())
99	    })?;
100	
101	    let to_book = book.clone();
102	    crawl.handle(
103	        &category,
104	        async move |ctx: CrawlContext<CategoryPayload>| {
105	            let payload = ctx.request().payload().clone();
106	            let links = ctx.page().locator("article.product_pod h3 a");
107	            let to = BookPayload {
108	                category: payload.name.clone(),
109	            };
110	            ctx.enqueue_links(&links, &to_book, to).await?;
111	            let next = ctx.page().locator("li.next a");
112	            ctx.enqueue_links(&next, ctx.request().label(), payload)
113	                .await?;
114	            Ok(())
115	        },
116	    )?;
117	
118	    let into = books.clone();
119	    crawl.handle(&book, async move |ctx: CrawlContext<BookPayload>| {
120	        let main = ctx.page().locator(".product_main");
121	        let text = main.text_content().await?;
122	        let price = text.split_once('£').map(|(_, rest)| {
123	            rest.chars()
124	                .take_while(|c| c.is_ascii_digit() || *c == '.')
125	                .collect::<String>()
126	        });
127	        let in_stock = between(&text, "(", " available)").and_then(|count| count.parse().ok());
128	        let stars = main
129	            .locator(".star-rating")
130	            .get_attribute("class")
131	            .await?
132	            .unwrap_or_default();
133	        let rating = RATINGS.iter().position(|word| stars.contains(word));
134	        let (Some(price), Some(in_stock), Some(rating)) =
135	            (price.filter(|p| !p.is_empty()), in_stock, rating)
136	        else {
137	            let message = format!("no price, stock or rating on the page (stars {stars:?})");
138	            return Err(ctx.skip(&message));
139	        };
140	        let record = Book {
141	            title: main.locator("h1").text_content().await?,
142	            price,
143	            in_stock,
144	            rating: rating as u8 + 1,
145	            url: ctx.page().url(), // the final URL, after redirects
146	            category: ctx.request().payload().category.clone(),
147	        };
148	        ctx.push(&into, &record).await
149	    })?;
150	
151	    Ok(BooksCrawl {
152	        crawl,
153	        books,
154	        home,
155	        book,
156	    })
157	}
