159	/// Runs the crawl, exports its Dataset and reports its requests.
160	pub async fn run(foxhound: &Foxhound) -> Result<(), Error> {
161	    let declared = books_crawl()?;
162	    let run = foxhound
163	        .start_crawl(&declared.crawl, declared.seeds())
164	        .await?;
165	    let report = declared.crawl.serve(&run).await?; // answers until the Run ends, then its report
166	    let exported = run.export(&declared.books, ExportFormat::Json).await?;
167	    exported.save_as("books.json").await?;
168	    println!("exported {} books to books.json", exported.records());
169	
170	    let kinds = [
171	        OutcomeKind::Failed,
172	        OutcomeKind::Skipped,
173	        OutcomeKind::Blocked,
174	    ];
175	    let mut outcomes = run.outcomes(OutcomesFilter::default().kinds(&kinds));
176	    while let Some(outcome) = outcomes.next().await {
177	        let outcome = outcome?;
178	        let url = &outcome.request.url;
179	        match &outcome.kind {
180	            CrawlRequestOutcomeKind::Failed(error) => {
181	                println!("failed {url}: {:?}: {}", error.code(), error.message());
182	            }
183	            CrawlRequestOutcomeKind::Skipped { reason, message } => {
184	                println!(
185	                    "skipped {url}: {reason:?} {}",
186	                    message.as_deref().unwrap_or("")
187	                );
188	            }
189	            CrawlRequestOutcomeKind::Blocked(cause) => println!("blocked {url}: {cause:?}"),
190	            _ => {}
191	        }
192	    }
193	    let totals = &report.requests;
194	    println!(
195	        "{} succeeded, {} failed, {} skipped, {} blocked",
196	        totals.succeeded, totals.failed, totals.skipped, totals.blocked
197	    );
198	    if let Some(nothing_done) = &report.run.nothing_done {
199	        println!("nothing done: {nothing_done:?}");
200	    }
201	    Ok(())
202	}
203	
204	#[tokio::main]
205	async fn main() -> Result<(), Error> {
206	    Foxhound::scope(ConnectOptions::default(), run).await
207	}

