6	use std::time::Duration;
7	
8	use goodfetch_foxhound::schemars::{self, JsonSchema};
9	use goodfetch_foxhound::settings::{ai, timeout};
10	use goodfetch_foxhound::{
11	    ConnectOptions, Crawl, CrawlContext, CrawlRequestOutcomeKind, Dataset, DatasetDeclaration,
12	    Error, Foxhound, Label, LabelDeclaration, Money, OutcomeKind, OutcomesFilter, Schema, Seed,
13	    Settings,
14	};
15	use serde::{Deserialize, Serialize};
16	
17	/// The Plan file: one entry for the book's extraction, compiled once per page layout (ADR 0091).
18	pub const PLAN: &str = "books.plan.json";
19	
20	/// What the model extracts from a book's page.
21	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
22	pub struct BookFields {
23	    /// The title.
24	    #[schemars(length(min = 1))]
25	    pub title: String,
26	    /// Pounds, exact.
27	    #[schemars(regex(pattern = r"^\d+\.\d{2}$"))]
28	    pub price: String,
29	    /// The number in stock.
30	    pub in_stock: u32,
31	    /// The star rating.
32	    #[schemars(range(min = 1, max = 5))]
33	    pub rating: u8,
34	}
35	
36	/// A book's Record.
37	#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
38	pub struct Book {
39	    /// What the model extracted.
40	    #[serde(flatten)]
41	    pub fields: BookFields,
42	    /// The book page's final URL.
43	    pub url: String,
44	}
45	
46	/// The crawl's declaration, with the handles a test needs.
47	#[derive(Debug)]
48	pub struct BookCrawl {
49	    /// The Labels and their handlers.
50	    pub crawl: Crawl<'static>,
51	    /// The books extracted.
52	    pub books: Dataset<Book>,
53	    /// The site's home page, the seed.
54	    pub home: Label<()>,
55	    /// A category's pages.
56	    pub category: Label<()>,
57	    /// A book's page.
58	    pub book: Label<()>,
59	}
60	
61	/// Declares the crawl. Each handler owns clones of the handles it uses.
62	pub fn crawl() -> Result<BookCrawl, Error> {
63	    let mut crawl = Crawl::new();
64	    let books = crawl.dataset(DatasetDeclaration::<Book>::new("books").key(&["url"]))?;
65	    let home = crawl.label::<()>("home")?;
66	    let category = crawl.label::<()>("category")?;
67	    // A first compile runs inside its handler, so it gets more than `timeout.handler`'s 60 s.
68	    let handler_timeout = Settings::new().set(timeout::HANDLER, Duration::from_secs(180));
69	    let book = crawl.label(LabelDeclaration::<()>::new("book").settings(handler_timeout))?;
70	
71	    let to_category = category.clone();
72	    crawl.handle(&home, async move |ctx: CrawlContext<()>| {
73	        let links = ctx.page().locator(".side_categories ul ul a");
74	        ctx.enqueue_links(&links, &to_category, ()).limit(3).await?;
75	        Ok(())
76	    })?;
77	
78	    let to_book = book.clone();
79	    crawl.handle(&category, async move |ctx: CrawlContext<()>| {
80	        let links = ctx.page().locator("article.product_pod h3 a");
81	        ctx.enqueue_links(&links, &to_book, ()).await?;
82	        let next = ctx.page().locator("li.next a");
83	        ctx.enqueue_links(&next, ctx.request().label(), ()).await?;
84	        Ok(())
85	    })?;
86	
87	    let to_books = books.clone();
88	    crawl.handle(&book, async move |ctx: CrawlContext<()>| {
89	        // The first book compiles the Plan entry; the next replay it with no model call, and a
90	        // page whose layout drifted gets one Repair. Past the Model allowance, a step that needs
91	        // the model fails with `model_allowance_reached`: returned, it ends this request
92	        // `skipped` (`model_allowance`).
93	        let step = ctx
94	            .page()
95	            .extract("the book on this page", Schema::<BookFields>::of())
96	            .await?;
97	        let record = Book {
98	            fields: step.output,
99	            url: ctx.page().url(),
100	        };
101	        ctx.push(&to_books, &record).await
102	    })?;
103	
104	    Ok(BookCrawl {
105	        crawl,
106	        books,
107	        home,
108	        category,
109	        book,
110	    })
111	}
112	
113	#[tokio::main]
114	async fn main() -> Result<(), Error> {
115	    let BookCrawl {
116	        crawl, home, book, ..
117	    } = crawl()?;
118	    let model = Settings::new().set(ai::MODEL, Some("vercel/openai/gpt-5-mini".into()));
119	    let foxhound = Foxhound::connect(ConnectOptions::default().settings(model)).await?;
120	    // The Model allowance: not a Limit, so the crawl goes on once it is spent.
121	    let allowance = Settings::new().set(ai::allowance::PRICE, Some(Money::new("0.50", "USD")?));
122	    let run = foxhound
123	        .start_crawl(
124	            &crawl,
125	            [Seed::new("https://books.toscrape.com/", &home, ())],
126	        )
127	        .plan(PLAN)
128	        .settings(allowance)
129	        .await?;
130	    // Serving is what lets a crawl finish: it returns the Run's report once the Run ends (ADR
131	    // 0102), `incomplete` when a book was skipped for the allowance.
132	    let report = crawl.serve(&run).await?;
133	
134	    let left = OutcomesFilter::default().kinds(&[OutcomeKind::Failed, OutcomeKind::Skipped]);
135	    let mut left = run.outcomes(left.label(&book));
136	    while let Some(outcome) = left.next().await {
137	        let outcome = outcome?;
138	        let url = &outcome.request.url;
139	        match &outcome.kind {
140	            CrawlRequestOutcomeKind::Skipped { reason, message } => {
141	                println!(
142	                    "unextracted {url}: {reason:?} {}",
143	                    message.as_deref().unwrap_or("")
144	                );
145	            }
146	            CrawlRequestOutcomeKind::Failed(error) => {
147	                let fix = error.fix().unwrap_or("");
148	                println!("unextracted {url}: {} {fix}", error.code().as_str());
149	            }
150	            _ => {}
151	        }
152	    }
153	
154	    let usage = &report.run.usage.model;
155	    let price = usage
156	        .price
157	        .as_ref()
158	        .map(|p| format!("{} {}", p.amount(), p.currency()));
159	    println!(
160	        "model use: {} tokens, {}",
161	        usage.tokens,
162	        price.as_deref().unwrap_or("unpriced")
163	    );
164	    run.as_run().close().await?;
165	    foxhound.close().await
166	}

